CREATE TABLE IF NOT EXISTS owner_claim(id INTEGER PRIMARY KEY CHECK(id=1),user_id TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS owner_setup(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS owner_limit(key TEXT PRIMARY KEY,start INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS single_owner BEFORE INSERT ON "user" WHEN EXISTS(SELECT 1 FROM "user") BEGIN SELECT RAISE(ABORT,'single owner'); END;
CREATE TABLE IF NOT EXISTS owner_device_invitation(hash TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS owner_device(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,name TEXT NOT NULL,credential_hash TEXT NOT NULL UNIQUE,invitation_hash TEXT NOT NULL UNIQUE,created INTEGER NOT NULL,last_seen INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS owner_device_connection(device_id TEXT PRIMARY KEY REFERENCES owner_device(id) ON DELETE CASCADE,connected INTEGER NOT NULL);
